// Unify whichever door fired into one canonical signup shape.
const j = $json;
const name = (j.name || '').toString().trim();
const parts = name.split(/\s+/).filter(Boolean);
return [{
  json: {
    email: (j.email || '').toString().trim().toLowerCase(),
    first_name: parts[0] || '',
    surname: parts.slice(1).join(' '),
    use_case: j.use_case || '',
    source: j.source || 'web',
    account_count: Number(j.account_count) || 0,
    signup_timestamp: $now.toISO()
  }
}];

