// Parse the inline-button tap: callback_data is "action:email".
const cq = $json.callback_query || {};
const raw = (cq.data || '').toString();
const idx = raw.indexOf(':');
const action = idx === -1 ? raw : raw.slice(0, idx);
const email = idx === -1 ? '' : raw.slice(idx + 1);
return [{
  json: {
    action,
    email: email.trim().toLowerCase(),
    message_id: cq.message && cq.message.message_id,
    chat_id: cq.message && cq.message.chat && cq.message.chat.id,
    original_text: (cq.message && cq.message.text) || ''
  }
}];

// Flow D entry — one webhook for everything a site form can say.
//   contact      a message from the contact form
//   newsletter   a request to subscribe (starts double opt-in)
//   confirm      the subscriber pressed the button behind the mailed link
//   unsubscribe  the same link, the other verb
// Anything else, or a submission missing what its kind needs, leaves as
// route 'invalid' and is answered 422 — never thrown, so a bad POST does not
// page the error workflow.
const SITE_NAME    = 'YOUR_SITE_NAME';
// The page on YOUR site that the mailed link opens. It shows a button and POSTs
// the token back through the sender; this workflow never serves a page itself.
const CONFIRM_PAGE = 'YOUR_CONFIRM_PAGE_URL';
// The sender subscribers see, e.g. 'Example <no-reply@example.com>'. Its domain
// has to be verified with the mail service the Send Confirm Email node calls.
const MAIL_FROM    = 'YOUR_FROM_ADDRESS';

const b = $json.body || {};
const clip = (v, n) => String(v ?? '').trim().slice(0, n);

const kind  = clip(b.kind, 20);
const email = clip(b.email, 200).toLowerCase();
const name  = clip(b.name, 120);
const parts = name.split(/\s+/).filter(Boolean);
const message = clip(b.message, 4000);
const given = clip(b.token, 64);
const tokenOk = /^[A-Za-z0-9-]{16,64}$/.test(given);
const emailOk = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);

// The sender should mint the token (a server has a real random source). This is
// the stand-in for a sender that does not.
const mint = () => Array.from({ length: 4 }, () => Math.random().toString(36).slice(2, 10)).join('');

let route = 'invalid';
if (kind === 'contact' && emailOk && message) route = 'contact';
if (kind === 'newsletter' && emailOk) route = 'newsletter';
if ((kind === 'confirm' || kind === 'unsubscribe') && tokenOk) route = 'token';

return [{
  json: {
    route,
    kind,
    ts: clip(b.ts, 40) || $now.toISO(),
    email,
    name,
    first_name: parts[0] || '',
    surname: parts.slice(1).join(' '),
    message,
    path: clip(b.path, 200),
    token: route === 'newsletter' ? (tokenOk ? given : mint()) : (tokenOk ? given : ''),
    site_name: SITE_NAME,
    confirm_page: CONFIRM_PAGE,
    mail_from: MAIL_FROM,
  },
}];

// Decide whether this request earns a confirmation mail.
//
// The form is public, so anyone can type anyone's address into it. Without this
// gate that is a way to mail a stranger as often as you like. So: an address
// that is already confirmed gets nothing, and a pending one gets at most one
// mail per RESEND_AFTER_H. The form answers the same either way — it must not
// tell a visitor whether an address is on the list.
const RESEND_AFTER_H = 24;

const s   = $('Shape Reach').first().json;
const cur = $('Lookup Subscriber').first().json || {};

const state  = String(cur.state || '');
const last   = Date.parse(String(cur.requested_at || ''));
const recent = Number.isFinite(last) && (Date.now() - last) < RESEND_AFTER_H * 3600e3;
const send   = !(state === 'confirmed' || (state === 'pending' && recent));

const link = s.confirm_page + '?a=confirm&t=' + s.token;

return [{
  json: {
    send: send ? 'yes' : '',
    email: s.email,
    token: s.token,
    requested_at: s.ts,
    path: s.path,
    subject: 'Confirm your subscription to ' + s.site_name,
    text: [
      'Someone asked to subscribe this address to updates from ' + s.site_name + '.',
      '',
      'If that was you, confirm here:',
      link,
      '',
      'If it was not you, ignore this mail. Nothing more is sent to an address that has not been confirmed.',
      '',
      'This address does not take replies.',
    ].join('\n'),
  },
}];

// Turn a token into a state change on the one Subscribers row that owns it.
//   confirm      pending -> confirmed. Already confirmed is a quiet yes. An
//                unsubscribed row is NOT revived by an old link: subscribing
//                again starts from the form and a fresh token.
//   unsubscribe  anything -> unsubscribed, and repeating it is a quiet yes.
const s   = $('Shape Reach').first().json;
const cur = $('Find By Token').first().json || {};

if (!cur.email || String(cur.token || '') !== s.token) return [{ json: { found: '' } }];

const now = $now.toISO();
let state = String(cur.state || '');
let confirmed_at = String(cur.confirmed_at || '');
let unsubscribed_at = String(cur.unsubscribed_at || '');

if (s.kind === 'confirm') {
  if (state === 'unsubscribed') return [{ json: { found: '' } }];
  if (state !== 'confirmed') { state = 'confirmed'; confirmed_at = now; }
} else {
  if (state !== 'unsubscribed') { state = 'unsubscribed'; unsubscribed_at = now; }
}

return [{
  json: {
    found: 'yes',
    kind: s.kind,
    email: String(cur.email).trim().toLowerCase(),
    state,
    confirmed_at,
    unsubscribed_at,
    path: String(cur.path || ''),
  },
}];

// What the contact book should learn from what just happened. Two flows end
// here, so this node reads whichever one ran — and only that one: naming a node
// that did not execute throws.
const s = $('Shape Reach').first().json;

if (s.route === 'contact') {
  return [{
    json: {
      email: s.email,
      first_name: s.first_name,
      surname: s.surname,
      group_add: 'contact',
      group_remove: '',
      association: 'site-contact',
      topic: 'Site message · ' + (s.path || '/'),
      note: s.message.slice(0, 500),
    },
  }];
}

const t = $('Apply Token').first().json;
const joined = t.state === 'confirmed';
return [{
  json: {
    email: t.email,
    first_name: '',
    surname: '',
    group_add: joined ? 'newsletter' : '',
    group_remove: joined ? '' : 'newsletter',
    association: 'site-newsletter',
    topic: joined ? 'Newsletter · confirmed' : 'Newsletter · unsubscribed',
    note: '',
  },
}];

// Build the Entries write. The next node auto-maps and matches on email, so it
// writes exactly the keys emitted here and nothing else.
//   known contact  only what changed: groups, last_topic, contact_updated_at.
//                  Their name, status and notes were curated elsewhere and a
//                  web form is not a reason to overwrite them.
//   new contact    a full starting row.
// Someone leaving the newsletter who was never in the book is not added to it.
const c   = $('Contact Change').first().json;
const cur = $('Contact Lookup').first().json || {};
const known = !!cur.email;

if (!known && !c.group_add) return [];

const groups = new Set(String(cur.groups || '').split(',').map((g) => g.trim()).filter(Boolean));
if (c.group_add) groups.add(c.group_add);
if (c.group_remove) groups.delete(c.group_remove);

const now = $now.toISO();
const row = {
  email: c.email,
  groups: [...groups].join(', '),
  last_topic: c.topic,
  contact_updated_at: now,
};
if (!known) {
  Object.assign(row, {
    first_name: c.first_name,
    surname: c.surname,
    status: 'lead',
    association: c.association,
    notes: c.note,
    contact_created_at: now,
  });
}
return [{ json: row }];

// Briefing plugin — the SITE INBOX section.
// Contract: 05_daily-briefing/docs/briefing-plugin-spec.md
//
// PLAIN TEXT ONLY — never HTML. The briefing escapes centrally, and everything
// printed here was typed by a stranger.
//
// Nothing pings when a form is sent; this section is the only place a message
// or a signup is announced, so it prints the message itself, not a count.
const WINDOW_H  = 24;
const MAX_MSGS  = 6;     // each can run to MSG_CHARS; the 4096 cap is shared
const MSG_CHARS = 500;
const MAX_SUBS  = 10;

const input = $('Called').first().json;
const tz    = input.tz || 'UTC';
const since = Date.now() - WINDOW_H * 3600e3;

const ts    = (v) => { const n = Date.parse(String(v || '')); return Number.isFinite(n) ? n : null; };
const fresh = (v) => { const n = ts(v); return n !== null && n >= since; };
const hhmm  = (v) => new Date(ts(v)).toLocaleTimeString('en-GB', { hour: '2-digit', minute: '2-digit', hour12: false, timeZone: tz });
const flat  = (v) => String(v ?? '').replace(/\s+/g, ' ').trim();

const messages = $('Get Messages').all().map((i) => i.json).filter((r) => r && r.email && fresh(r.ts));
const subs     = $('Get Subscribers').all().map((i) => i.json).filter((r) => r && r.email);

messages.sort((a, b) => ts(b.ts) - ts(a.ts));
const msgItems = messages.slice(0, MAX_MSGS).map((m) => {
  const who  = flat(m.name) ? flat(m.name) + ' <' + flat(m.email) + '>' : flat(m.email);
  const body = flat(m.message);
  const text = body.length > MSG_CHARS ? body.slice(0, MSG_CHARS) + '…' : body;
  return who + ' · ' + hhmm(m.ts) + ' · ' + (flat(m.path) || '/') + '\n    ' + text;
});
if (messages.length > MAX_MSGS) msgItems.push('+' + (messages.length - MAX_MSGS) + ' more in the Messages tab');

// One row per address, so one line per address: the latest thing that happened.
const events = [];
for (const s of subs) {
  const from = flat(s.path) ? ' · from ' + flat(s.path) : '';
  if (s.state === 'unsubscribed' && fresh(s.unsubscribed_at)) events.push({ at: ts(s.unsubscribed_at), text: flat(s.email) + ' · unsubscribed' });
  else if (s.state === 'confirmed' && fresh(s.confirmed_at)) events.push({ at: ts(s.confirmed_at), text: flat(s.email) + ' · confirmed' + from });
  else if (s.state === 'pending' && fresh(s.requested_at)) events.push({ at: ts(s.requested_at), text: flat(s.email) + ' · asked, not confirmed yet' + from });
}
events.sort((a, b) => b.at - a.at);
const subItems = events.slice(0, MAX_SUBS).map((e) => e.text);
if (events.length > MAX_SUBS) subItems.push('+' + (events.length - MAX_SUBS) + ' more in the Subscribers tab');

const count = (state) => subs.filter((s) => s.state === state).length;
const totals = count('confirmed') + ' confirmed · ' + count('pending') + ' pending · ' + count('unsubscribed') + ' unsubscribed';
if (subItems.length) subItems.push('List: ' + totals);

// Always exactly one item — zero items is indistinguishable from a crash.
return [{
  json: {
    key: 'reach',
    icon: '📬',
    title: 'SITE INBOX',
    blocks: [
      { heading: 'Messages', items: msgItems },
      { heading: 'Newsletter', items: subItems },
    ],
    empty: 'Nothing new · list: ' + totals,
  },
}];
